function canonicalBusinessDate(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [year, month, day2] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day2));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day2) return null;
  return value;
}

