// services/rajarshiRates.ts
var addDays = (iso, n) => {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(y, m - 1, d + n);
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
};
function tierForDate(hotel, date) {
  for (const tier of hotel.tiers) {
    for (const w of tier.windows) {
      if (date >= w.from && date <= w.to) return tier;
    }
  }
  return null;
}
function resolveNightRate(hotel, room, plan, date) {
  const tier = tierForDate(hotel, date);
  if (!tier) {
    const base = room.rates.base?.[plan];
    return { date, tierId: "base", rate: base ?? 0, isOnRequest: base == null };
  }
  if (tier.mode === "surcharge") {
    const base = room.rates.base?.[plan];
    if (base == null) return { date, tierId: tier.id, tierLabel: tier.label, rate: 0, isOnRequest: true };
    return { date, tierId: tier.id, tierLabel: tier.label, rate: base + (tier.surcharge || 0), isOnRequest: false };
  }
  const tierRate = room.rates[tier.id]?.[plan];
  if (tierRate != null) return { date, tierId: tier.id, tierLabel: tier.label, rate: tierRate, isOnRequest: false };
  return { date, tierId: tier.id, tierLabel: tier.label, rate: 0, isOnRequest: true };
}
function quoteStay(i) {
  const perNight = [];
  let netRoomTotal = 0;
  let anyOnRequest = false;
  for (let n = 0; n < i.nights; n++) {
    const date = addDays(i.checkIn, n);
    const nr = resolveNightRate(i.hotel, i.room, i.plan, date);
    perNight.push(nr);
    if (nr.isOnRequest) anyOnRequest = true;
    else netRoomTotal += nr.rate * i.rooms;
  }
  const extraRate = i.hotel.extraPerson?.base?.[i.plan] ?? 0;
  const extraPersonTotal2 = i.extraPersons * extraRate * i.nights;
  const netCost = netRoomTotal + extraPersonTotal2;
  const markupAmount = i.markupMode === "percent" ? Math.round(netRoomTotal * i.markupValue / 100) : Math.round(i.markupValue * i.nights * i.rooms);
  const sellingPrice = netCost + markupAmount;
  return { perNight, anyOnRequest, netRoomTotal, markupAmount, extraPersonTotal: extraPersonTotal2, netCost, sellingPrice, profit: markupAmount };
}

// services/inlandRates.ts
function quoteInlandStay(i) {
  const rate = i.column === 1 ? i.room.rate1 : i.room.rate2;
  const onRequest = i.column === 1 ? i.room.onRequest1 : i.room.onRequest2;
  const rawText = i.column === 1 ? i.room.raw1 : i.room.raw2;
  const columnLabel = i.room.axisLabels[i.column - 1];
  if (onRequest || rate == null) {
    return { columnLabel, isOnRequest: true, rawText, baseRate: 0, netRoomTotal: 0, extraPersonTotal: 0, netCost: 0, markupAmount: 0, sellingPrice: 0 };
  }
  const netRoomTotal = rate * i.nights * i.rooms;
  const extraRate = typeof i.room.childAdult === "number" ? i.room.childAdult : 0;
  const extraPersonTotal2 = i.extraPersons * extraRate * i.nights;
  const netCost = netRoomTotal + extraPersonTotal2;
  const markupAmount = i.markupMode === "percent" ? Math.round(netRoomTotal * i.markupValue / 100) : Math.round(i.markupValue * i.nights * i.rooms);
  const sellingPrice = netCost + markupAmount;
  return { columnLabel, isOnRequest: false, baseRate: rate, netRoomTotal, extraPersonTotal: extraPersonTotal2, netCost, markupAmount, sellingPrice };
}
function suggestSeason(checkInISO) {
  const month = Number(checkInISO.slice(5, 7));
  return month >= 4 && month <= 9 ? "H1" : "H2";
}
function hotelsByCity() {
  const out = {};
  for (const h of INLAND_HOTELS) (out[h.city] ||= []).push(h);
  return out;
}

